import pytest

from dijkstra import dijkstra


def bellman_ford(adj, src):
    """Oracle: relax all edges |V| times. Handles positive weights; unreachable
    nodes are simply absent from the result."""
    nodes = set(adj.keys())
    for edges in adj.values():
        for v, _ in edges:
            nodes.add(v)
    dist = {n: float("inf") for n in nodes}
    dist[src] = 0
    edges = [(u, v, w) for u, nbrs in adj.items() for v, w in nbrs]
    for _ in range(len(nodes)):
        changed = False
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            break
    return {n: d for n, d in dist.items() if d != float("inf")}


def test_direct_edge_hides_cheaper_two_hop_path():
    # Minimal failing graph: the expensive direct edge a->b is relaxed first,
    # freezing b's distance at 10 before the cheaper route a->c->b (5) is found.
    # (a->c appears after a->b in adjacency order, so c is discovered on a later
    # iteration and can never lower the already-frozen dist[b].)
    adj = {
        "a": [("b", 10), ("c", 1)],
        "c": [("b", 4)],
    }
    assert dijkstra(adj, "a") == {"a": 0, "c": 1, "b": 5}


def test_unreachable_nodes_excluded():
    adj = {
        "a": [("b", 2)],
        "b": [],
        "lonely": [],          # present but no incoming edge from a
    }
    result = dijkstra(adj, "a")
    assert "lonely" not in result
    assert result == {"a": 0, "b": 2}


def test_self_loop_is_harmless():
    adj = {
        "a": [("a", 7), ("b", 3)],  # self-loop with positive weight must be ignored
        "b": [("b", 2)],
    }
    assert dijkstra(adj, "a") == {"a": 0, "b": 3}


@pytest.mark.parametrize("seed", range(300))
def test_fuzz_against_bellman_ford(seed):
    rng = random.Random(seed)
    n = rng.randint(0, 12)
    nodes = [f"n{i}" for i in range(n)]
    adj = {u: [] for u in nodes}
    max_edges = n * n
    for _ in range(rng.randint(0, max_edges)):
        u, v = rng.choice(nodes), rng.choice(nodes)
        adj[u].append((v, rng.randint(1, 20)))
    if not nodes:
        assert dijkstra(adj, "x") == {}
        return
    src = rng.choice(nodes)
    got = dijkstra(adj, src)
    want = bellman_ford(adj, src)
    assert got == want, f"seed={seed}\ngot ={got}\nwant={want}"
"})
